    JunctionTableOps::JunctionCache::instance().invalidateTable(WORK_BINDERS_JUNCTION_TABLE);
    JunctionTableOps::JunctionCache::instance().invalidateTable(WORK_DICT_WORDS_JUNCTION_TABLE);
    JunctionTableOps::JunctionCache::instance().invalidateTable(WORK_TAGS_JUNCTION_TABLE);

